js:
var out = root.querySelector('.mdi-stream-thread-out');
var state = root.querySelector('[data-state]');
var tok = root.querySelector('[data-tok]');
var stopBtn = root.querySelector('[data-act="stop"]');
var replayBtn = root.querySelector('[data-act="replay"]');
var log = root.querySelector('.mdi-stream-thread-log');
var TEXT = 'The 01:42 UTC rollout tripped the health gate: 4 of 6 pods failed /readyz after the migration lock timed out. The controller reverted to build 3f91c on its own. Nothing was lost, the write queue drained before the cutover.';
var i = 0, timer = null;
function halt(done){
  clearInterval(timer); timer = null;
  root.classList.add('is-done');
  var s = done ? 'complete' : 'stopped';
  state.textContent = s;
  state.setAttribute('data-state', s);
  stopBtn.disabled = true;
}
function run(){
  clearInterval(timer);
  i = 0; out.textContent = '';
  root.classList.remove('is-done');
  state.textContent = 'streaming';
  state.setAttribute('data-state', 'streaming');
  stopBtn.disabled = false;
  tok.textContent = '0 tok';
  timer = setInterval(function(){
    if (!root.isConnected) { clearInterval(timer); return; }
    i = Math.min(TEXT.length, i + 2 + Math.floor(Math.random() * 3));
    out.textContent = TEXT.slice(0, i);
    tok.textContent = Math.max(1, Math.ceil(i / 4)) + ' tok';
    log.scrollTop = log.scrollHeight;
    if (i >= TEXT.length) halt(true);
  }, 30);
}
stopBtn.addEventListener('click', function(){ if (timer) halt(false); });
replayBtn.addEventListener('click', run);
run();

