var label = root.querySelector('[data-label]');
var time = root.querySelector('[data-time]');
var fill = root.querySelector('[data-fill]');
var btn = root.querySelector('.mdi-think-pulse-cancel');
var steps = Array.prototype.slice.call(root.querySelectorAll('.mdi-think-pulse-step'));
var SPAN = 1.3, TOTAL = steps.length, timer = null, elapsed = 0, cur = -1;
function mark(n){
  cur = n;
  steps.forEach(function(s, i){
    s.classList.toggle('is-done', i < n);
    s.classList.toggle('is-live', i === n);
  });
  label.textContent = 'Working · step ' + (n + 1) + ' of ' + TOTAL;
}
function finish(){
  clearInterval(timer); timer = null;
  steps.forEach(function(s){ s.classList.add('is-done'); s.classList.remove('is-live'); });
  root.classList.add('is-done');
  label.textContent = 'Answer ready';
  fill.style.width = '100%';
  btn.textContent = 'Run again';
}
function start(){
  clearInterval(timer);
  elapsed = 0;
  root.classList.remove('is-done', 'is-stopped');
  btn.textContent = 'Cancel';
  fill.style.width = '0%';
  mark(0);
  timer = setInterval(function(){
    if (!root.isConnected) { clearInterval(timer); return; }
    elapsed += 0.1;
    time.textContent = elapsed.toFixed(1) + 's';
    var n = Math.floor(elapsed / SPAN);
    if (n !== cur && n < TOTAL) mark(n);
    fill.style.width = Math.min(100, (elapsed / (SPAN * TOTAL)) * 100).toFixed(1) + '%';
    if (elapsed >= SPAN * TOTAL) finish();
  }, 100);
}
btn.addEventListener('click', function(){
  if (!timer) { start(); return; }
  clearInterval(timer); timer = null;
  root.classList.add('is-stopped');
  steps.forEach(function(s){ s.classList.remove('is-live'); });
  label.textContent = 'Cancelled';
  btn.textContent = 'Run again';
});
start();

