var input = root.querySelector('.mdi-prompt-dock-input');
var send = root.querySelector('.mdi-prompt-dock-send');
var hint = root.querySelector('[data-hint]');
var count = root.querySelector('[data-count]');
var chips = Array.prototype.slice.call(root.querySelectorAll('.mdi-prompt-dock-chip'));
function active(){
  return chips.filter(function(c){ return c.getAttribute('aria-pressed') === 'true'; })
              .map(function(c){ return c.getAttribute('data-tool'); });
}
function tools(){
  var a = active();
  hint.classList.remove('is-sent');
  hint.textContent = a.length ? a.join(' + ') + ' enabled' : 'No tools enabled';
}
function grow(){
  input.style.height = 'auto';
  input.style.height = Math.min(86, input.scrollHeight) + 'px';
}
function sync(){
  var v = input.value.trim();
  send.disabled = v.length === 0;
  count.textContent = input.value.length + ' / 400';
  count.classList.toggle('is-near', input.value.length > 340);
  grow();
}
function submit(){
  var v = input.value.trim();
  if (!v) return;
  var a = active();
  input.value = '';
  sync();
  hint.textContent = 'Sent' + (a.length ? ' with ' + a.join(' + ') : '');
  hint.classList.add('is-sent');
  setTimeout(function(){ if (root.isConnected) tools(); }, 1800);
}
chips.forEach(function(c){
  c.addEventListener('click', function(){
    c.setAttribute('aria-pressed', c.getAttribute('aria-pressed') === 'true' ? 'false' : 'true');
    tools();
  });
});
input.addEventListener('input', sync);
input.addEventListener('keydown', function(e){
  if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); submit(); }
});
send.addEventListener('click', submit);
tools();
sync();

