var trigger = root.querySelector('.mdi-model-switch-trigger');
var now = root.querySelector('[data-now]');
var meta = root.querySelector('[data-meta]');
var opts = Array.prototype.slice.call(root.querySelectorAll('.mdi-model-switch-opt'));
var open = false;
function setOpen(v, moveFocus){
  open = v;
  root.classList.toggle('is-open', v);
  trigger.setAttribute('aria-expanded', v ? 'true' : 'false');
  if (v && moveFocus) {
    var sel = opts.filter(function(o){ return o.getAttribute('aria-selected') === 'true'; })[0] || opts[0];
    sel.focus();
  }
}
function select(o){
  opts.forEach(function(x){ x.setAttribute('aria-selected', x === o ? 'true' : 'false'); });
  now.textContent = o.getAttribute('data-name');
  meta.textContent = o.getAttribute('data-meta');
  setOpen(false, false);
  trigger.focus();
}
trigger.addEventListener('click', function(){ setOpen(!open, true); });
trigger.addEventListener('keydown', function(e){
  if (e.key === 'ArrowDown' && !open) { e.preventDefault(); setOpen(true, true); }
});
opts.forEach(function(o, i){
  o.addEventListener('click', function(){ select(o); });
  o.addEventListener('keydown', function(e){
    if (e.key === 'ArrowDown') { e.preventDefault(); opts[(i + 1) % opts.length].focus(); }
    else if (e.key === 'ArrowUp') { e.preventDefault(); opts[(i - 1 + opts.length) % opts.length].focus(); }
    else if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(o); }
    else if (e.key === 'Escape') { e.preventDefault(); setOpen(false, false); trigger.focus(); }
  });
});
setOpen(true, false);

