var SETS = [
  ['Summarise this thread', 'Draft a reply to Priya', 'Explain the schema change', 'Find the slowest query'],
  ['Compare Q2 and Q3 churn', 'Write the release notes', 'Review this migration', 'List the open blockers'],
  ['Rewrite this shorter', 'Add tests for the parser', 'Estimate the API cost', 'Sketch a rollout plan']
];
var wrap = root.querySelector('[data-chips]');
var out = root.querySelector('[data-out]');
var shuffle = root.querySelector('.mdi-suggest-deck-shuffle');
var set = 0;
function pick(text, pill){
  Array.prototype.slice.call(wrap.children).forEach(function(p){ p.classList.remove('is-picked'); });
  pill.classList.add('is-picked');
  out.textContent = '> ' + text;
  out.classList.add('is-loaded');
}
function render(){
  wrap.textContent = '';
  SETS[set].forEach(function(text, i){
    var b = document.createElement('button');
    b.type = 'button';
    b.className = 'mdi-suggest-deck-pill';
    b.textContent = text;
    b.style.setProperty('--mdi-suggest-deck-d', (i * 55) + 'ms');
    b.addEventListener('click', function(){ pick(text, b); });
    wrap.appendChild(b);
  });
  out.textContent = 'Pick one to load it into the composer.';
  out.classList.remove('is-loaded');
}
shuffle.addEventListener('click', function(){
  set = (set + 1) % SETS.length;
  render();
});
render();

