var copy = root.querySelector('[data-act="copy"]');
var copyText = root.querySelector('[data-copytext]');
var retry = root.querySelector('[data-act="retry"]');
var retryText = root.querySelector('[data-retrytext]');
var up = root.querySelector('[data-act="up"]');
var down = root.querySelector('[data-act="down"]');
var panel = root.querySelector('[data-panel]');
var toast = root.querySelector('[data-toast]');
var answer = root.querySelector('.mdi-reply-actions-answer');
var reasons = Array.prototype.slice.call(root.querySelectorAll('.mdi-reply-actions-reason'));
var send = root.querySelector('.mdi-reply-actions-send');
function say(msg){
  toast.textContent = msg;
  setTimeout(function(){ if (root.isConnected && toast.textContent === msg) toast.textContent = ''; }, 2200);
}
copy.addEventListener('click', function(){
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      var job = navigator.clipboard.writeText(answer.textContent.trim());
      if (job && job.catch) job.catch(function(){});
    }
  } catch (err) {}
  copy.classList.add('is-ok');
  copyText.textContent = 'Copied';
  setTimeout(function(){
    if (!root.isConnected) return;
    copy.classList.remove('is-ok');
    copyText.textContent = 'Copy';
  }, 1500);
});
retry.addEventListener('click', function(){
  retry.classList.add('is-busy');
  retryText.textContent = 'Regenerating';
  setTimeout(function(){
    if (!root.isConnected) return;
    retry.classList.remove('is-busy');
    retryText.textContent = 'Retry';
    say('New answer generated (v2)');
  }, 1400);
});
function rate(btn, other, msg){
  var on = btn.getAttribute('aria-pressed') === 'true';
  btn.setAttribute('aria-pressed', on ? 'false' : 'true');
  other.setAttribute('aria-pressed', 'false');
  panel.hidden = !(btn === down && !on);
  if (!on) say(msg); else toast.textContent = '';
}
up.addEventListener('click', function(){ rate(up, down, 'Marked helpful'); });
down.addEventListener('click', function(){ rate(down, up, 'Tell us what missed'); });
reasons.forEach(function(r){
  r.addEventListener('click', function(){
    r.setAttribute('aria-pressed', r.getAttribute('aria-pressed') === 'true' ? 'false' : 'true');
  });
});
send.addEventListener('click', function(){
  panel.hidden = true;
  reasons.forEach(function(r){ r.setAttribute('aria-pressed', 'false'); });
  say('Thanks, feedback sent');
});
